from __future__ import annotations

from typing import Any, Dict, Iterable, List, Mapping, Optional, Union

import os

try:
    import deepl
except ImportError as e:
    raise ImportError(
        "The deepl package is required. Install it with: pip install deepl"
    ) from e


def _normalize_target_lang(target_lang: str) -> str:
    lang = target_lang.strip().replace("_", "-").upper()
    if "-" in lang:
        lang = lang.split("-")[0]
    return lang


def _extract_text(result: Any) -> str:
    if isinstance(result, str):
        return result
    if hasattr(result, "text"):
        return result.text
    return str(result)


def translate_dictionary_values(
    data: Mapping[str, Any],
    target_lang: str,
    source_lang: Optional[str] = None,
    auth_key: Optional[str] = None,
) -> Dict[str, Any]:
    auth = auth_key or os.getenv("DEEPL_AUTH_KEY")
    if not auth:
        raise ValueError("DEEPL_AUTH_KEY must be provided via argument or environment variable.")

    translator = deepl.Translator(auth)
    target = _normalize_target_lang(target_lang)
    source = source_lang.strip().upper() if source_lang else None

    def translate_value(value: Any) -> Any:
        if isinstance(value, dict):
            return {k: translate_value(v) for k, v in value.items()}
        if isinstance(value, list):
            return [translate_value(v) for v in value]
        if isinstance(value, tuple):
            return tuple(translate_value(v) for v in value)
        if isinstance(value, str):
            if not value:
                return value
            translated = translator.translate_text(
                value,
                source_lang=source,
                target_lang=target,
            )
            return _extract_text(translated)
        return value

    return {k: translate_value(v) for k, v in data.items()}
